// Path to the external markdown file for system instructions
var systemPromptFile = Path.Combine(Data.GetFolder(), "gemini_system_prompt.txt");

Program.Setup(() => {
    // This method is used to register this program as a "AI intent handler"
    Program.Implements(
        "@AI:WidgetGenie",
        "AI.WidgetGenie/Gemini", new { chat = new { requestVersion = 1, context = new [] { "devices", "widgets", "automationPrograms", "dashboards", "deepKnowledge" }, capabilities = new string[0] } }
    ).AddOption("ApiKey", "", "1. Google Gemini AI API key", "password")
     .AddOption("ModelId", "gemini-flash-latest", "2. Model ID", "text")
     .AddOption("EnableDeepKnowledge", "On", "3. Enable Deep Knowledge (Read programs & widgets)", "checkbox")
     .AddOption("SystemInstructions", "", "4. System Instructions", $"editor:file:{systemPromptFile}:markdown");
});

