public class MessagePart {
    [JsonProperty("text")]
    public string Text { get; set; }
}

public class ChatMessage {
    [JsonProperty("role")]
    public string Role { get; set; }
    [JsonProperty("parts")]
    public List<MessagePart> Parts { get; set; } = new List<MessagePart>();

    public static ChatMessage Create(string role, string text) {
        return new ChatMessage {
            Role = role,
            Parts = new List<MessagePart> { new MessagePart { Text = text } }
        };
    }
}
// Diagnostics stay in the history envelope, never in provider message objects.
public class ChatRequestMetrics
{
    readonly dynamic api;
    readonly string storeId;
    readonly bool persist;
    readonly System.Diagnostics.Stopwatch clock = System.Diagnostics.Stopwatch.StartNew();
    readonly DateTimeOffset startedAt = DateTimeOffset.UtcNow;
    public string ContextProfileKey { get; set; }
    public string RequestId { get; } = Guid.NewGuid().ToString("N");
    public long? FirstTokenMs { get; private set; }
    public long? GenerationMs { get; private set; }
    public long ActionsMs { get; private set; }
    public int ActionCount { get; private set; }
    public int FailedActions { get; private set; }
    bool replySaved;

    public ChatRequestMetrics(dynamic api, string storeId, bool persist = true)
    { this.api = api; this.storeId = storeId; this.persist = persist; }

    public void FirstToken() { if (!FirstTokenMs.HasValue) FirstTokenMs = clock.ElapsedMilliseconds; }
    public void GenerationComplete() { GenerationMs = clock.ElapsedMilliseconds; }
    public void ActionsCompleted(long elapsedMs, int count, int failed)
    { ActionsMs += elapsedMs; ActionCount += count; FailedActions += failed; }
    public object Snapshot(string outcome) => new {
        contextProfileKey = ContextProfileKey, requestId = RequestId, startedAt = startedAt.ToString("O"), outcome,
        durationMs = clock.ElapsedMilliseconds, firstTokenMs = FirstTokenMs,
        generationMs = GenerationMs, actionsMs = ActionsMs,
        actionCount = ActionCount, failedActions = FailedActions
    };
    public void SaveUser(object message)
    { if (persist) api.Call("System.Utility/ChatHistory/Add", new { StoreId = storeId, Message = message, Metadata = Snapshot("submitted") }); }
    public void SaveReply(object message, string outcome = "completed")
    {
        if (replySaved) return;
        if (persist) api.Call("System.Utility/ChatHistory/Add", new { StoreId = storeId, Message = message, Metadata = Snapshot(outcome) });
        replySaved = true;
    }
    public dynamic CallAction(string command, object data = null)
    {
        var timer = System.Diagnostics.Stopwatch.StartNew();
        bool failed = false;
        try {
            object result = api.Call(command, data);
            if (result == null) failed = true;
            else {
                try {
                    var token = result is string ? JToken.Parse((string)result) : JToken.FromObject(result);
                    failed = token.Type == JTokenType.Object && (token["Status"]?.ToString() == "Error"
                        || token["State"]?.ToString() == "failed" || token["State"]?.ToString() == "unknown");
                    if (command.EndsWith("Programs.Compile") && token is JArray errors && errors.Count > 0) failed = true;
                } catch (Newtonsoft.Json.JsonException) { }
            }
            return result;
        } catch { failed = true; throw; }
        finally { ActionsCompleted(timer.ElapsedMilliseconds, 1, failed ? 1 : 0); }
    }
    public string Error(string text, string outcome = "error")
    {
        SaveReply(new { role = "model", parts = new[] { new { text } } }, outcome);
        return text;
    }
}

public static class CompositeSolutionContract
{
    public static JObject Validate(JObject solution)
    {
        var program = solution["automation"] as JObject;
        var widget = solution["widget"] as JObject;
        var binding = solution["binding"] as JObject;
        if (program == null || widget == null || binding == null)
            throw new InvalidOperationException("A composite solution requires automation, widget and binding.");
        foreach (var key in new[] { "name", "main" })
            if (program[key]?.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)program[key]))
                throw new InvalidOperationException("Missing automation " + key + ".");
        if (program["setup"]?.Type != JTokenType.String || widget["html"]?.Type != JTokenType.String
            || string.IsNullOrWhiteSpace((string)widget["html"]) || widget["javascript"]?.Type != JTokenType.String)
            throw new InvalidOperationException("Incomplete composite sources.");
        if (!new[] { "csharp", "javascript", "python" }.Contains((string)solution["language"]))
            throw new InvalidOperationException("Unsupported automation language.");
        string domain = (string)binding["domain"], address = (string)binding["address"];
        if (string.IsNullOrWhiteSpace(domain) || domain.IndexOfAny(new[] { '/', ':', '\\' }) >= 0
            || string.IsNullOrWhiteSpace(address) || address.IndexOfAny(new[] { '/', ':', '\\' }) >= 0)
            throw new InvalidOperationException("Invalid module reference.");
        if (address == "$program" && domain != "HomeAutomation.HomeGenie.Automation")
            throw new InvalidOperationException("$program refers to the automation program module.");
        var properties = binding["properties"] as JArray;
        if (properties == null || properties.Count == 0 || properties.Count > 64
            || properties.Any(p => p.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)p)))
            throw new InvalidOperationException("Declare the properties required by the widget.");
        return (JObject)binding.DeepClone();
    }
    public static JObject Resolve(JObject binding, string programId)
    {
        var resolved = (JObject)binding.DeepClone();
        if ((string)resolved["address"] == "$program") resolved["address"] = programId;
        return resolved;
    }
}

public static class WidgetContextRequest
{
    public static readonly string[] ContextKeys = { "devices", "widgets", "automationPrograms", "dashboards", "deepKnowledge" };
    public static void Validate(JObject input)
    {
        if (input.Properties().Any(p => !new[] { "version", "message", "context", "resources", "dashboards" }.Contains(p.Name)))
            throw new InvalidOperationException("Unknown structured prompt field.");
        if (input["version"]?.Type != JTokenType.Integer || (int)input["version"] != 1
            || input["message"]?.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)input["message"]))
            throw new InvalidOperationException("A structured prompt requires version 1 and a nonempty message.");
        if (input["resources"] != null && !(input["resources"] is JObject))
            throw new InvalidOperationException("Resources must be an object.");
        if (input["resources"] is JObject resources) {
            if (resources.Properties().Any(p => p.Name != "programIds" && p.Name != "widgetIds"))
                throw new InvalidOperationException("Unknown context resource field.");
            foreach (var p in resources.Properties())
                if (!(p.Value is JArray ids) || ids.Count > 16 || ids.Any(id => id.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)id)))
                    throw new InvalidOperationException("Resources must contain at most 16 nonempty string IDs.");
        }
        if (input["dashboards"] != null && (!(input["dashboards"] is JArray dashboards) || dashboards.Count > 100))
            throw new InvalidOperationException("Dashboards must be an array with at most 100 entries.");
    }
    public static JArray FilterHistory(JArray history, string profileKey)
    {
        var matching = history.OfType<JObject>().Where(m => (string)m["metadata"]?["contextProfileKey"] == profileKey).ToList();
        var completed = new HashSet<string>(matching.Where(m => (string)m["role"] == "model" && (string)m["metadata"]?["outcome"] == "completed")
            .Select(m => (string)m["metadata"]?["requestId"]).Where(id => !string.IsNullOrEmpty(id)));
        return JArray.FromObject(matching.Where(m => completed.Contains((string)m["metadata"]?["requestId"] ?? "")
            && ((string)m["metadata"]?["outcome"] == "completed" || ((string)m["role"] == "user" && (string)m["metadata"]?["outcome"] == "submitted")))
            .Select(m => new { role = m["role"], parts = m["parts"] }));
    }
    public static JObject ProgramSummary(JObject program) => new JObject {
        ["program_id"] = program["Address"], ["name"] = program["Name"], ["description"] = program["Description"],
        ["language"] = program["Type"], ["enabled"] = program["IsEnabled"]
    };
    public static JArray DashboardSummary(JArray input)
    {
        var output = new JArray();
        foreach (var token in input) {
            if (!(token is JObject dashboard) || dashboard["name"]?.Type != JTokenType.String || !(dashboard["widgets"] is JArray widgets) || widgets.Count > 1000)
                throw new InvalidOperationException("Invalid dashboard context.");
            output.Add(new JObject { ["name"] = dashboard["name"], ["widgets"] = JArray.FromObject(widgets.OfType<JObject>().Select(w => new {
                componentId = w["componentId"], moduleId = (w["module"] as JObject)?["moduleId"], adapterId = (w["module"] as JObject)?["adapterId"]
            })) });
        }
        return output;
    }
}

public static class AiPromptTemplate
{
    public static JObject Read(string file, Func<string, object, object> call)
    {
        string template = File.ReadAllText(file, new UTF8Encoding(false, true));
        // Old/custom prompt files remain valid and do not require a catalog service.
        if (!System.Text.RegularExpressions.Regex.IsMatch(template, @"(?m)^\s*#use-(?:skill|kb)(?:\s|$)")) {
            string hash;
            using (var sha = SHA256.Create()) hash = BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(template))).Replace("-", "").ToLowerInvariant();
            return new JObject { ["version"] = 1, ["prompt"] = template, ["skills"] = new JArray(), ["resources"] = new JArray(), ["fingerprint"] = hash };
        }
        object raw = call("System.Utility/ContextEngine/Prompt.Compose", new { version = 1, template });
        if (raw == null) throw new InvalidOperationException("Prompt composition is unavailable; update Context Engine and install the shared skills.");
        JToken result = raw is string text ? JToken.Parse(text) : JToken.FromObject(raw);
        if (result["Status"]?.ToString() == "Error") throw new InvalidOperationException("Prompt composition failed: " + result["Message"]);
        if (!(result is JObject composed) || composed["version"]?.Type != JTokenType.Integer || (int)composed["version"] != 1
            || composed["prompt"]?.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)composed["prompt"])
            || !(composed["skills"] is JArray) || !(composed["resources"] is JArray) || composed["fingerprint"]?.Type != JTokenType.String)
            throw new InvalidOperationException("Prompt composition returned an invalid response.");
        return composed;
    }
    public static string Load(string file, Func<string, object, object> call) => (string)Read(file, call)["prompt"];
    public static object Summary(JObject composed) => new {
        version = 1, fingerprint = (string)composed["fingerprint"],
        skills = composed["skills"], resources = composed["resources"],
        promptBytes = Encoding.UTF8.GetByteCount((string)composed["prompt"])
    };
}

ProgramBlock.ScriptSource:
var inputModules = Modules.WithFeature(InstanceSegmentation);
var requestsPerSecond = Program.Option(YoloRequestsPerSecond);

// Show toggle icon for this algorithm in the NVR / Video widget
Program
    .Emit("NVR.Vision.Algorithm", InstanceSegmentation)     // feature to toggle "On" in order to enable this algo
    .Emit("NVR.Vision.Algorithm.Icon", "pattern");          // material symbol icon for the toggle button

// Restart program if configuration has been changed to apply new settings.
When.ModuleParameterChanged( (module, property) => {
    if (module.Instance == Program.Module && property.Name.StartsWith("ConfigureOptions."))
    {
        if (Program.IsRunning) Program.Restart();
        return true;
    }
    return true;
});

var yoloModelPath = Program.Option("Yolo.ModelPath")?.Value;
if (String.IsNullOrEmpty(yoloModelPath))
{
    Program.Notify($"Configure the path of YOLO 'segment' model (.onnx file). {OptionButtons}");
    Pause(5);
    return;
}

var breathe = () => {
    if (requestsPerSecond.DecimalValue > 0)
    {
        Pause(1D / requestsPerSecond.DecimalValue);
    }
    else
    {
        Pause(0.2); // default is 5 RPS max
    }
};

// For details about this implemention see
// *ML.net* and *YoloSharp* documentation


try
{
    var errorOccurred = false;
    using var detectPredictor = new YoloPredictor(yoloModelPath);
    while (Program.IsRunning)
    {
        if (inputModules.SelectedModules.Count == 0)
        {
            Pause(1);
            continue;
        }
        inputModules.Each((module) => {
            var data = module.Command("Camera.GetPicture").GetValue();
            if (data == null || ((byte[])data).Length == 0)
            {
                // I/O errors might occasionally occur and can be ignored
                return false;
            }
            try
            {
                var result = detectPredictor.Segment((byte[])data);
                //Console.WriteLine($"Result: {result}");
                //Console.WriteLine($"Speed:  {result.Speed}");
                if (result.Count() > 0)
                {
                    var output = new List<SegmentResult>();
                    // Emit "Sensor.ObjectDetect.Subject.Data" event if anything
                    // mathing the configured "TriggerDetect" list
                    // was detected in the scene.
                    string[] matchList = module
                        .Parameter( InstanceSegmentationTrigger )?.Value
                        .Split(',').Select(p => p.Trim())
                        .Where(x => !string.IsNullOrEmpty(x))
                        .ToArray();
                    if (matchList.Length > 0)
                    {
                        var filtered = new List<Compunet.YoloSharp.Data.Segmentation>();
                        foreach (var r in result)
                        {
                            var subject = r.Name.Name;
                            if (matchList.Contains(subject))
                            {
                                filtered.Add(r);
                            }
                        }
                        if (filtered.Count > 0)
                        {
                            if (module.Parameter(ObjectDetect).DecimalValue != filtered.Count)
                            {
                                module.Emit(ObjectDetect, filtered.Count);
                            }
                            else
                            {
                                // update value and timestamp only, do not emit event
                                module.Parameter(ObjectDetect).SetData(filtered.Count);
                            }
                            foreach (var r in filtered)
                            {
                                output.Add(new SegmentResult(){
                                    Result = r,
                                    Mask = ExtractAndApproximateContour(r.Mask, 100)
                                });
                                module.Emit(ObjectDetectSubject, r);
                            }
                        }
                        else if (module.Parameter(ObjectDetect).DecimalValue != 0 && module.Parameter(ObjectDetect).IdleTime > 5)
                        {
                            module.Emit(ObjectDetect, 0);
                        }
                    }
                    else
                    {
                        foreach (var r in result)
                        {
                            output.Add(new SegmentResult(){
                                Result = r,
                                Mask = ExtractAndApproximateContour(r.Mask, 100)
                            });
                        }
                    }

                    if (output.Count > 0)
                    {
                        // Emit json data for the video player (overlay data)
                        var jsonResults = JsonConvert.SerializeObject(output);
                        module.Emit(VideoPlayerWidgetOverlaySegment, jsonResults);
                    }

                }
            }
            catch (Exception e)
            {
                errorOccurred = true;
                //Console.WriteLine(e.Message);
            }
            if (errorOccurred)
            {
                errorOccurred = false;
                Pause(3);
            }
            else
            {
                breathe();
            }
            return false;
        });
        breathe();
    }
}
catch (Exception e)
{
    Program.Notify($"Error: {e.Message} {OptionButtons}");
    Pause(5);
    return;
}

ProgramBlock.ScriptContext:
#using Compunet.YoloSharp.Memory

const string
OptionButtons = "[program_configure,program_disable]",
YoloModelPath = "Yolo.ModelPath",
YoloRequestsPerSecond = "Yolo.RequestsPerSecond",
ForCameraInputType = "VideoInput,Sensor:Widget.DisplayModule=/homegenie/generic/(videoinput|camerainput)/",
InstanceSegmentation = "ML.InstanceSegmentation",
InstanceSegmentationTrigger = $"{InstanceSegmentation}.TriggerDetect",
ObjectDetect = "Sensor.ObjectDetect",
ObjectDetectSubject = "Sensor.ObjectDetect.Subject",
VideoPlayerWidgetOverlaySegment = "Widget.Data.VideoPlayer.Overlay.Segment";

public class SegmentResult
{
    public Compunet.YoloSharp.Data.Segmentation Result;
    public List<MaskPoint> Mask;
}

public class MaskPoint
{
    public float X;
    public float Y;
    public MaskPoint(float x, float y)
    {
        X = x;
        Y = y;
    }
}

public static List<MaskPoint> ExtractAndApproximateContour(BitmapBuffer r, int maxPoints = 25)
{
    var contour = ExtractContourPointsInternal(r);  // Get the initial contour

    if (contour.Count <= maxPoints)
    {
        return contour; // No need to approximate if already within the limit
    }

    // Implement a simple approximation by taking equally spaced points
    var approximatedContour = new List<MaskPoint>();
    double interval = (double)contour.Count / maxPoints;
    for (int i = 0; i < maxPoints - 1; i++)
    {
        int index = (int)Math.Round(i * interval); //Round for accuracy
        approximatedContour.Add(contour[index]); // Add existing point at the index
    }

    //Ensure the loop has the final item; If the last isn't added, add it
    if(approximatedContour.Last() != contour.Last()) {
            approximatedContour.Add(contour.Last());
    }

    return approximatedContour;
}


private static List<MaskPoint> ExtractContourPointsInternal(BitmapBuffer r)
{
    int height = r.Height;
    int width = r.Width;

    // Helper function to check if a pixel is a border pixel
    bool IsBorderPixel(BitmapBuffer mask, int x, int y)
    {
        if (x == 0 || x == width - 1 || y == 0 || y == height - 1)
        {
            return true;
        }

        return (mask[y, x - 1] > 0.9 != mask[y, x] > 0.9 ||
                mask[y, x + 1] > 0.9 != mask[y, x] > 0.9 ||
                mask[y - 1, x] > 0.9 != mask[y, x] > 0.9 ||
                mask[y + 1, x] > 0.9 != mask[y, x] > 0.9);
    }

    // Find all contour pixels
    var contourPixels = new List<MaskPoint>();
    for (int y = 0; y < height; y++)
    {
        for (int x = 0; x < width; x++)
        {
            if (r[y, x] > 0.9 && IsBorderPixel(r, x, y))
            {
                contourPixels.Add(new MaskPoint(x, y));
            }
        }
    }

    if (contourPixels.Count == 0)
    {
        return new List<MaskPoint>(); // Return empty list if no shape found
    }

    // Order the contour pixels (nearest neighbor approach)
    var contour = new List<MaskPoint>();
    var startPixel = contourPixels[0];
    contour.Add(startPixel);
    contourPixels.Remove(startPixel);

    var currentPixel = startPixel;

    while (contourPixels.Count > 0)
    {
        var nearestNeighbor = contourPixels
            .OrderBy(p => Math.Sqrt(Math.Pow(p.X - currentPixel.X, 2) + Math.Pow(p.Y - currentPixel.Y, 2))) // Euclidean distance
            .FirstOrDefault();

        if (nearestNeighbor == null)  // No more neighbors found
        {
            break;
        }

        contour.Add(nearestNeighbor);
        contourPixels.Remove(nearestNeighbor);
        currentPixel = nearestNeighbor;
    }

    return contour;
}

ProgramBlock.ScriptSetup:
// ===================================================================
// SETUP BLOCK - PROGRAM INITIALIZATION
// ===================================================================
// This block is executed once when the program is enabled.
// It is responsible for:
// 1. Loading the available models for the UI selection.
// 2. Registering the program as a system-wide AI Intent Handler.
// 3. Defining user-configurable options (tokens, model, prompt).
// 4. Linking the specific front-end chat widget.
// ===================================================================

// --- 1. PRE-SETUP CONFIGURATION DATA ---

// Load available GGUF models from models.yaml to populate the dropdown
var modelsList = LoadModelList(Path.Combine(Data.GetFolder(), CONFIG_FILE_NAME));
var models = string.Join(",", modelsList.Select(item => $"{item.Value.Name}={item.Key}"));

// Path to the external markdown file for system instructions
var systemPromptFile = Path.Combine(Data.GetFolder(), "system_prompt.txt");
var modelsFile = Path.Combine(Data.GetFolder(), CONFIG_FILE_NAME);


// --- 2. PROGRAM SETUP DELEGATE ---

Program.Setup(() => {

  Program
    // Implement the AI Intent Handler interface to allow system integration
    .Implements(
      "@AI:IntentHandler",
      API_URL
    )

    // UI Options Definition:
    // - Response length limit (Max Tokens)
    // - Model selection dropdown (populated from models.yaml)
    // - System Instructions (Markdown editor linked to system_prompt.txt)
    .AddOption(OPTION_MODEL_FILE, "", "0. AI Model", $"select:{ models }")
    .AddOption(OPTION_SEND_CONTEXT_DATA, "On", "1. Share system and module context with the AI", "checkbox")
    .AddOption(OPTION_MODEL_TEMPERATURE, "0.4", "2. Creativity (0.0 = Precise, 2.0 = Creative)", "slider:0.0:2.0:0.05")
    .AddOption(OPTION_CONTEXT_SIZE, "2048", "3. AI Memory Capacity (Context Window)", "slider:1024:32768:1024")
    .AddOption(OPTION_MAX_TOKENS, "1536", "4. Response Length (Max Tokens)", "slider:64:4096:32")
    .AddOption(OPTION_MAX_TURNS, "10", "5. Chat Memory (Max Turns) (0 = no limit)", "slider:0:20:1")
    .AddOption(OPTION_SYSTEM_INSTRUCTIONS, "", "6. System Prompt (Instructions)", $"editor:file:{systemPromptFile}:markdown")
    .AddOption(OPTION_MODEL_LIST, "", "7. AI Model List", $"editor:file:{modelsFile}:yaml")

    // Assign the custom UI widget for the chat interface
    .UseWidget("custom/examples/local-ai-chat")
    .Emit("@AI:IntentHandler", API_URL); // notify widgets

});


// --- 3. EXECUTION ---

// Trigger the transition to the MAIN block
Program.Run();

ProgramBlock.ScriptSource:
// ===================================================================
// LOCAL LLM AUTOMATION PROGRAM (LLamaSharp Edition)
// ===================================================================
// This block manages the integration of a Local Language Model (GGUF)
// for home automation control within HomeGenie.
//
// Main Responsibilities:
// 1. Model download management via System DownloadManager.
// 2. LLamaSharp engine initialization (VRAM/RAM management).
// 3. Dynamic device inventory generation for the System Prompt.
// 4. Token streaming with smart buffering and artifact filtering.
// 5. Automatic execution of API commands extracted from AI responses.
// ===================================================================

// --- 1. CONFIGURATION AND STATE INITIALIZATION ---

var reconfigureRequired = false;
int maxMessages = (int)Program.Option(OPTION_MAX_TURNS).DecimalValue * 2;
var modelsFile = Path.Combine(Data.GetFolder(), CONFIG_FILE_NAME);

// Load model configurations and file paths
var modelsList = LoadModelList(modelsFile);
var selectedModel = Program.Option(OPTION_MODEL_FILE).Value;
string localModelFile = Path.Combine(Data.GetFolder(), selectedModel);



// Register event handler to trigger a restart if configuration options change.
When.ModuleParameterChanged((module, parameter) => {
  if (module.Instance == Program.Module && parameter.Name.StartsWith("ConfigureOptions.")) {
    if (parameter.Name.EndsWith($".{OPTION_MODEL_LIST}"))
    {
      // Update model list option in the UI
      modelsList = LoadModelList(modelsFile);
      var models = string.Join(",", modelsList.Select(item => $"{item.Value.Name}={item.Key}"));
      models = $"select:{ models }";
      // IMPORTANT: update only if changed to prevent loop Emit <-> ModuleParameterChanged
      if (parameter.Value != models)
      {
        Program.Option(OPTION_MODEL_FILE).FieldType = models;
      }
    }
    else
    {
      reconfigureRequired = true;
    }
  }
  return true;
});



// Reset UI status fields
Program
  .Emit("LLM.Id", "")
  .Emit("Status.System.RamGb", GetTotalMemoryGB())
  .Emit(FIELD_STATUS_INIT, "NotConfigured");


// --- 2. API: DOWNLOAD MANAGEMENT ---
// These endpoints bridge the UI with the system's DownloadManager utility.

Api.Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadStart", (p) => {
     var model = modelsList[selectedModel];
     Program.Emit(FIELD_STATUS_INIT, "Download").Emit(FIELD_DOWNLOAD, "Requested");
     var item = JsonConvert.SerializeObject(new {
         Name = model.Name,
         Url = model.Url,
         Path = Data.GetFolder()
     });
     Api.Call("System.Utility/DownloadManager/Enqueue", item);
     return new ResponseStatus(Status.Ok);

}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadCancel", (p) => {
     Program.Emit(FIELD_DOWNLOAD, "Pending");
     var item = JsonConvert.SerializeObject(new { Id = Program.Parameter(FIELD_DOWNLOAD_ID)?.Value });
     Api.Call("System.Utility/DownloadManager/Delete", item);
     Program
      .Emit(FIELD_DOWNLOAD_ID, "")
      .Emit(Program.Option(OPTION_MODEL_FILE).Name, "");
     return new ResponseStatus(Status.Ok);

}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadPause", (p) => {
    Program.Emit(FIELD_DOWNLOAD, "Paused");
    var item = JsonConvert.SerializeObject(new { Id = Program.Parameter(FIELD_DOWNLOAD_ID)?.Value });
    Api.Call("System.Utility/DownloadManager/Pause", item);
    return new ResponseStatus(Status.Ok);

}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/DownloadResume", (p) => {
    var item = JsonConvert.SerializeObject(new { Id = Program.Parameter(FIELD_DOWNLOAD_ID)?.Value });
    Api.Call("System.Utility/DownloadManager/Resume", item);
    return new ResponseStatus(Status.Ok);
});


// --- 2.1 INFERENCE POST-PROCESSING HELPER METHOD (shared for using by other programs)
Api.Handle($"{Program.Module.Domain}/{Program.Module.Address}/Extract", (modelResponse) => {
    return ExtractResponse(ReadActionResponse(modelResponse));
}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/Execute", (modelResponse) => {
    return ExecuteResponse(ReadActionResponse(modelResponse));
}).Handle($"{Program.Module.Domain}/{Program.Module.Address}/ExtractAndExecute", (modelResponse) => {
    return ExtractAndExecute(ReadActionResponse(modelResponse));
});


// --- 3. MODEL FILE VERIFICATION & MONITORING LOOP ---

if (!File.Exists(localModelFile)) {
  // Wait for finalization, not just 100% of bytes received into the .part file.
  while (Program.IsRunning)
  {
    if (reconfigureRequired) return;
    object response = Api.Call("System.Utility/DownloadManager/GetStatus", localModelFile);
    // The service can be temporarily unregistered during startup or a package update.
    // Keep the same polling loop alive; never restart the program or load a partial model.
    dynamic fileStatus = null;
    try {
      if (response is string statusJson && !string.IsNullOrWhiteSpace(statusJson))
        fileStatus = JObject.Parse(statusJson);
      else if (response is JObject statusObject) fileStatus = statusObject;
    } catch (Newtonsoft.Json.JsonException) {
      // An unavailable/incomplete status is transient. Pause below and try again.
    }

    if (fileStatus?.Success == true)
    {
      var task = fileStatus?.Data;
      if (task != null)
      {
        // Update UI with real-time download progress
        Program
          .Emit(FIELD_DOWNLOAD, task.Status.ToString())
          .Emit(FIELD_DOWNLOAD_ID, task.Id.ToString())
          .Emit(FIELD_DOWNLOAD_TASK, task.DestinationFilePath.ToString())
          .Emit(FIELD_DOWNLOAD_ERROR, task.ErrorMessage?.ToString() ?? "")
          .Emit(FIELD_DOWNLOAD_PROGRESS, task.ProgressPercentage.ToString("F2", CultureInfo.InvariantCulture));

        // The downloader closes and moves the file before reporting Completed.
        // Paused/Error tasks may also have 100% progress: keep them recoverable.
        if (string.Equals(task.Status?.ToString(), "Completed", StringComparison.OrdinalIgnoreCase)
            && File.Exists(localModelFile)) break;
      }
      else if (Program.Parameter(FIELD_DOWNLOAD_TASK)?.Value != localModelFile)
      {
        // No active task found for this file
        Program
          .Emit(FIELD_DOWNLOAD, "Pending")
          .Emit(FIELD_DOWNLOAD_ID, String.IsNullOrEmpty(selectedModel) ? "Pending" : "")
          .Emit(FIELD_DOWNLOAD_TASK, localModelFile)
          .Emit(FIELD_DOWNLOAD_PROGRESS, "0");
          if (modelsList.ContainsKey(selectedModel))
          {
            Program.Emit(FIELD_DOWNLOAD_REPOSITORY, modelsList[selectedModel].Repository);
          }
          else
          {
            Program.Emit(FIELD_DOWNLOAD_REPOSITORY, "");
          }
      }
    }

    if (reconfigureRequired) return;
    Pause(2); // Poll status every 2 seconds
  }

  if (!Program.IsRunning || reconfigureRequired) return;

  Program
    .Emit(FIELD_STATUS_ERROR, "")
    .Emit(FIELD_DOWNLOAD, "Complete")
    .Emit(FIELD_DOWNLOAD_PROGRESS, "100");

  // Continue into engine initialization in this run; no Setup/Main restart.
}
else if (Program.Parameter(FIELD_DOWNLOAD_TASK)?.Value != localModelFile)
{
  // File already exists; ensure UI state is consistent
  Program
    .Emit(FIELD_DOWNLOAD, "Complete")
    .Emit(FIELD_DOWNLOAD_ID, "")
    .Emit(FIELD_DOWNLOAD_PROGRESS, "100")
    .Emit(FIELD_DOWNLOAD_TASK, localModelFile);
}


// --- 4. LLM ENGINE INITIALIZATION (LLamaSharp) ---

Program
  .Emit("LLM.Id", selectedModel)
  .Emit(FIELD_STATUS_ERROR, "")
  .Emit(FIELD_STATUS_INIT, $"Starting");

var templateType = "";
var modelPath = localModelFile;

if (modelsList.ContainsKey(selectedModel)) {
  templateType = modelsList[selectedModel].Template;
} else {
  // ERROR: selected model not listed
  modelPath = "";
  Program
    .Emit(FIELD_DOWNLOAD_ID, "")
    .Emit(Program.Option(OPTION_MODEL_FILE).Name, "");
}

LLamaWeights model = null;
LLamaContext context = null;
ChatSession session = null;
LLama.SessionState resetState = null;
var nativeLifetime = new LailamaNativeLifetime();
Action<string> lifecycleLog = message => { try { Program.Log.Info(message); } catch { } };

// Release only after loading/inference has stopped. Native disposal itself runs in
// a background task, so a stalled native backend cannot indefinitely block shutdown.
var dispose = new Action(() => nativeLifetime.Stop(() => {
  session = null;
  try {
    if (resetState?.ContextState != null) {
      lifecycleLog("Lailama shutdown: disposing saved context state.");
      resetState.ContextState.Dispose(); resetState = null;
      lifecycleLog("Lailama shutdown: saved context state disposed.");
    }
  } finally {
  try {
    if (context != null) {
      lifecycleLog("Lailama shutdown: disposing context.");
      context.Dispose(); context = null;
      lifecycleLog("Lailama shutdown: context disposed.");
    }
  } finally {
    if (model != null) {
      lifecycleLog("Lailama shutdown: disposing model weights.");
      model.Dispose(); model = null;
      lifecycleLog("Lailama shutdown: model weights disposed.");
    }
  }
  }
}, lifecycleLog));

// Basic path validation
if (String.IsNullOrEmpty(modelPath))
{
  Program.Notify($"LLM model path not configured.[program_configure]").Emit(FIELD_STATUS_ERROR, "LLM model path not configured.");
}
else if (!File.Exists(modelPath))
{
  Program.Notify($"File not found: {modelPath}.[program_configure]").Emit(FIELD_STATUS_ERROR, $"File not found: {modelPath}");
}
else
{
  // Ensure cleanup on stop
  When.ProgramStopping(() => { dispose(); return true; });

  CancellationTokenSource initializationCts;
  if (!nativeLifetime.TryBegin(out initializationCts)) return;
  try {
    initializationCts.Token.ThrowIfCancellationRequested();
    // Load Inference Parameters
    LailamaInferenceParams.MaxTokens = (int)Program.Option(OPTION_MAX_TOKENS).DecimalValue;
    uint contextSize = (uint)Program.Option(OPTION_CONTEXT_SIZE).DecimalValue;

    var parameters = GetOptimizedParams(modelPath);

    // Load Model Weights and Context
    model = LLamaWeights.LoadFromFile(parameters);
    initializationCts.Token.ThrowIfCancellationRequested();
    context = model.CreateContext(parameters);
    initializationCts.Token.ThrowIfCancellationRequested();

    var executor = new InteractiveExecutor(context);
    var chatHistory = new ChatHistory();

    // --- 5. SYSTEM PROMPT CONFIGURATION AND CHAT SESSION INIT ---
    var promptText = "";
    try { promptText = File.ReadAllText(Path.Combine(Data.GetFolder(), "system_prompt.txt")); } catch (Exception e) { }

    var systemPrompt = (string)Api.Call("System.Utility/ContextEngine/Render", promptText);

    // Clean initialization
    var systemMessage = new ChatHistory.Message(AuthorRole.System, (string)systemPrompt);
    chatHistory.Messages.Add(systemMessage);


    // SYNC: Fetch clean history from the System Service and sync LLamaSharp session
    string storeId = Program.Module.Address;
    try {
        var result = Api.Call("System.Utility/ChatHistory/GetContext", new { StoreId = storeId });
        dynamic unifiedlHistory = JArray.FromObject(result).ToObject<List<ChatMessage>>();

        if (unifiedlHistory != null) {

            // Re-populate with clean messages from service
            foreach(ChatMessage msg in unifiedlHistory) {
                var role = msg.Role == "user" ? AuthorRole.User : AuthorRole.Assistant;

                // --- FIX: Uso di un ciclo classico invece di LINQ .Select() ---
                var partsTextList = new List<string>();
                foreach (var part in msg.Parts) {
                    partsTextList.Add(part.Text);
                }
                string combinedText = string.Join("\n", partsTextList);
                chatHistory.Messages.Add(new ChatHistory.Message(role, combinedText));
            }
        }
    } catch (Exception ex) {
        Program.Log.Error("Sync error: " + ex.Message);
    }


    // Final session starts with the System Prompt already in history
    session = new ChatSession(executor, chatHistory);

    resetState = session.GetSessionState();
    session.LoadSession(resetState);

    // --- 6. WARMUP PHASE ---
    // Perform a dummy inference to pre-populate the KV cache and avoid latency on first use.
    Program.Emit(FIELD_STATUS_INIT, "WarmingUp");
    try {
        var warmupParams = new InferenceParams() { MaxTokens = 1 };
        var warmupCancellation = initializationCts;
        var warmup = Task.Run(async () => {
            await foreach (var token in session.ChatAsync(new ChatHistory.Message(AuthorRole.User, " "), warmupParams, cancellationToken: warmupCancellation.Token)) { }
        });
        try { warmup.GetAwaiter().GetResult(); }
        catch (ThreadInterruptedException) {
            // The host may interrupt Main while the native warmup is still unwinding.
            // Transfer ownership to the worker: never release its context prematurely.
            warmup.ContinueWith(_ => nativeLifetime.End(warmupCancellation), TaskScheduler.Default);
            initializationCts = null;
            throw;
        }
    } catch (ThreadInterruptedException) { throw; }
    catch (OperationCanceledException) when (nativeLifetime.IsStopping) { throw; }
    catch (Exception ex) {
        Program.Log.Warn($"Warmup warning: {ex.Message}");
    }
    // Ready is emitted after chat APIs are registered.


    // --- 7. INFERENCE LOGIC AND TOKEN PROCESSING ---
    /**
      * Processes the user input, handles LLM inference, manages the token stream,
      * and synchronizes with the centralized Chat History Service.
      *
      * @param rawInput The clean text entered by the user.
      * @param synchronous Whether to wait for the full response before returning.
      * @return The full generated response (if synchronous), otherwise an empty string.
      */
    var processInput = new Func<string, bool, bool, bool, string>((rawInput, synchronous, sendContextData, noHistory) => {

        var telemetry = new ChatRequestMetrics(Api, storeId, !noHistory);


        string fullInput = rawInput;
        if (sendContextData)
        {
          string systemInfo = (string)Api.Call("System.Utility/ContextEngine/Render", "%%SYSTEM_STATUS%%");
          fullInput = systemInfo + "\n\n" + rawInput;
        }


        // 3. TEMPLATING: Prepare input for the engine (but don't save this to history!)
        string templatedInput = BuildUserPrompt(templateType, fullInput);

        CancellationTokenSource requestCts;
        if (!nativeLifetime.TryBegin(out requestCts))
            throw new InvalidOperationException("Local AI is busy or stopping. Wait for the current operation to finish.");
        try { telemetry.SaveUser(ChatMessage.Create("user", rawInput)); }
        catch { nativeLifetime.End(requestCts); throw; }

        var process = new Func<bool, string>((sync) => {
            try {
            requestCts.Token.ThrowIfCancellationRequested();
            // Send the templated input to the engine
            var sessionChat = session.ChatAsync(
                new ChatHistory.Message(AuthorRole.User, templatedInput),
                LailamaInferenceParams,
                cancellationToken: requestCts.Token
            );

            string streamBuffer = "";
            string fullReply = "";
            var technicalTags = LailamaInferenceParams.AntiPrompts.Where(x => x.StartsWith("<")).ToArray();
            var textStops = LailamaInferenceParams.AntiPrompts.Where(x => !x.StartsWith("<")).ToArray();
            string[] visualArtifacts = { "/assistant/avatar", "/avatar", "![avatar]", "![image]" };

            ProcessAsync(sessionChat, (token) => {
                if (nativeLifetime.IsStopping || string.IsNullOrEmpty(token)) return;
                telemetry.FirstToken();
                streamBuffer += token;
                fullReply += token;

                foreach (var art in visualArtifacts) if (streamBuffer.Contains(art)) streamBuffer = streamBuffer.Replace(art, "");
                foreach (var tag in technicalTags) if (streamBuffer.Contains(tag)) streamBuffer = streamBuffer.Replace(tag, "");
                foreach (var stop in textStops) {
                    if (streamBuffer.EndsWith(stop)) { streamBuffer = ""; return; }
                }

                bool isPotentialDanger = false;
                foreach (var stop in textStops) if (stop.StartsWith(streamBuffer)) { isPotentialDanger = true; break; }

                if (!isPotentialDanger || streamBuffer.Length > 25) {
                    Program.Emit(FIELD_TOKENS_STREAM, streamBuffer);
                    streamBuffer = "";
                }
            }).GetAwaiter().GetResult();

            if (!string.IsNullOrEmpty(streamBuffer)) {
                foreach (var tag in technicalTags) streamBuffer = streamBuffer.Replace(tag, "");
                if (!string.IsNullOrWhiteSpace(streamBuffer)) Program.Emit(FIELD_TOKENS_STREAM, streamBuffer);
            }
            Program.Emit(FIELD_TOKENS_STREAM, "");

            // Some inference backends finish normally when cancelled. Never execute a partial reply.
            requestCts.Token.ThrowIfCancellationRequested();

            // 4. COMMAND EXECUTION AND PERSISTENCE
            var messageSegments = ExtractResponse(fullReply);
            telemetry.GenerationComplete();
            var actionTimer = System.Diagnostics.Stopwatch.StartNew();
            var actionResults = ExecuteResponse(fullReply, telemetry.RequestId);
            telemetry.SetActionResults(actionResults);
            telemetry.ActionsCompleted(actionTimer.ElapsedMilliseconds, actionResults.Count, actionResults.Count(r => !r.Success));

            var modelResponse = new ChatMessage {
                Role = "model",
                Parts = messageSegments.Select(s => new MessagePart { Text = s }).ToList()
            };

            if (!noHistory)
            {
              telemetry.SaveReply(modelResponse);
              Program.Emit("Widget.Refresh", "action_results");
            }

            if (sendContextData)
            {
              // Replace content with the clean text (without systemInfo)
              var lastUserMsg = session.History.Messages.LastOrDefault(m => m.AuthorRole == AuthorRole.User);
              if (lastUserMsg != null)
              {
                  lastUserMsg.Content = rawInput;
              }
            }

            // Check chat history (excluding the System Message at index 0)
            // If history size exceeds the limit (System + max allowed messages), start pruning.
            /*
            while (maxMessages > 0 && session.History.Messages.Count > maxMessages + 1)
            {
                // Remove the oldest message immediately following the System Message.
                // Index 1 represents the earliest User or Assistant message in the conversation.
                session.History.Messages.RemoveAt(1);
            }
            */
            if (session.History.Messages.Count > maxMessages)
            {
              session.LoadSession(resetState);
              session.History.Messages.Clear();
              //context.NativeHandle.MemoryClear(data: true);
              systemPrompt = (string)Api.Call("System.Utility/ContextEngine/Render", promptText);
              systemMessage = new ChatHistory.Message(AuthorRole.System, (string)systemPrompt);
              session.History.Messages.Add(systemMessage);
            }

            return fullReply;
            } catch (OperationCanceledException) {
                if (!nativeLifetime.IsStopping) telemetry.Error("[STOPPED]", "cancelled");
                throw;
            } catch (Exception) {
                if (!nativeLifetime.IsStopping) telemetry.Error("**Error:** Local AI inference failed. Please check the logs.");
                throw;
            } finally { nativeLifetime.End(requestCts); }
        });

        // A synchronous API caller may be an automation thread interrupted by the host.
        // The native worker, not that caller, owns and ends the operation lease.
        if (synchronous) return Task.Run(() => process(true)).GetAwaiter().GetResult();

        Task.Run(() => {
            try { process(false); }
            catch (OperationCanceledException) { lifecycleLog("Lailama inference stopped."); }
            catch (Exception ex) { if (!nativeLifetime.IsStopping) Program.Emit(FIELD_STATUS_ERROR, ex.Message); }
        });

        return "";
    });


    initializationCts.Token.ThrowIfCancellationRequested();
    // --- 8. API ENDPOINTS: INFERENCE AND CHAT ---

    Api.Handle($"{API_URL}/{API_PROMPT_SUBMIT}", (userInput) => {
        var request = Api.Parse(userInput);
        // Direct intent submission (e.g. from external modules or scripts)
        var input = userInput is string ? WebUtility.UrlDecode(userInput as string) : request?.Data is string ? request?.Data as string : Encoding.Default.GetString(request?.Data as byte[]);
        if (!String.IsNullOrWhiteSpace(input))
        {
            bool sendContextData = (Program.Option(OPTION_SEND_CONTEXT_DATA).Value == "On");
            processInput(input, false, sendContextData, false);
        }
        return new ResponseStatus(Status.Ok, "Processing: " + input);

    }).Handle($"{API_URL}/{API_PROMPT_SCHEDULE}", (command) => {
        var request = Api.Parse(command);
        // Direct intent submission (e.g. from external modules or scripts)
        var input = command is string ? WebUtility.UrlDecode(command as string) : request?.Data is string ? request?.Data as string : Encoding.Default.GetString(request?.Data as byte[]);
        if (!String.IsNullOrWhiteSpace(input))
        {
          return new ResponseStatus(Status.Ok, processInput(input, true, false, true));
        }
        return new ResponseStatus(Status.Error, "No input");

    }).Handle($"{API_URL}/{API_PROMPT_CANCEL}", (userCommand) => {
        // Abort current generation
        if (nativeLifetime.CancelCurrent()) Program.Emit(FIELD_TOKENS_STREAM, "\n\n[STOPPED]");
        return new ResponseStatus(Status.Ok);

    }).Handle($"{API_URL}/{API_HISTORY_GET}", (userCommand) => {

      return Api.Call("System.Utility/ChatHistory/Get", new {
          StoreId = Program.Module.Address
      });

    }).Handle($"{API_URL}/{API_HISTORY_CLEAR}", (userCommand) => {

      CancellationTokenSource clearCts;
      if (!nativeLifetime.TryBegin(out clearCts)) return new ResponseStatus(Status.Error, "Local AI is busy or stopping.");
      try {
      var storeId = Program.Module.Address;
      Api.Call("System.Utility/ChatHistory/Clear", new { StoreId = storeId });
      if (session != null && resetState != null)
      {
          session.LoadSession(resetState);
          if (session.History.Messages.Count > 0)
          {
              session.History.Messages.Clear();
              //context.NativeHandle.MemoryClear(data: true);
              systemPrompt = (string)Api.Call("System.Utility/ContextEngine/Render", promptText);
              systemMessage = new ChatHistory.Message(AuthorRole.System, (string)systemPrompt);
              session.History.Messages.Add(systemMessage);
          }
      }
      Program.Log.Info($"[Module {storeId}] Cleared: Engine and Service are now empty.");
      return new ResponseStatus(Status.Ok);
      } finally { nativeLifetime.End(clearCts); }

    });

    Api.Handle($"{API_URL}/{API_HISTORY_REMOVE_AT}", (i) => Api.Call("System.Utility/ChatHistory/RemoveAt", new { StoreId = storeId, Index = i }));
    Api.Handle($"{API_URL}/{API_HISTORY_EXPORT}", (p) => Api.Call("System.Utility/ChatHistory/Export", new { StoreId = storeId }));
    Api.Handle($"{API_URL}/{API_HISTORY_IMPORT}", (p) => Api.Call("System.Utility/ChatHistory/Import", new { StoreId = storeId, Data = (p as dynamic).Data }));

    initializationCts.Token.ThrowIfCancellationRequested();
    Program.Emit(FIELD_STATUS_INIT, "Ready");
    Program.Emit(FIELD_STATUS_ERROR, "");

  } catch (ThreadInterruptedException) { throw; }
  catch (OperationCanceledException) when (nativeLifetime.IsStopping) {
    lifecycleLog("Lailama initialization cancelled during shutdown.");
  } catch (Exception e) {
    if (!nativeLifetime.IsStopping) {
      Program.Notify($"ERROR: {e.Message} [program_configure]").Emit(FIELD_STATUS_ERROR, e.Message);
      Pause(5);
    } else lifecycleLog("Lailama initialization ended during shutdown: " + e.Message);
  } finally { if (initializationCts != null) nativeLifetime.End(initializationCts); }
}

Program.Emit(FIELD_TOKENS_STREAM, "");

// --- 9. KEEP-ALIVE AND LIFECYCLE MONITORING ---

while (Program.IsRunning)
{
    if (reconfigureRequired)
    {
        dispose();
        // Do not load another model while old native resources are still in use.
        while (Program.IsRunning && !nativeLifetime.CleanupCompleted) Pause(1);
        return; // Exiting this loop triggers HomeGenie to reload the program block
    }
    Pause(1);
}

ProgramBlock.ScriptContext:
#using System.Text.RegularExpressions

// ===================================================================
// CONFIGURATION AND CONSTANTS
// ===================================================================

/* Internal API Routing */
const string API_URL = "AI.IntentHandlers/Lailama";
const string API_PROMPT_SUBMIT = "Prompt.Submit";
const string API_PROMPT_SCHEDULE = "Prompt.Schedule";
const string API_PROMPT_CANCEL = "Prompt.Cancel";
const string API_HISTORY_GET = "History.Get";
const string API_HISTORY_CLEAR = "History.Clear";
const string API_HISTORY_REMOVE_AT = "History.RemoveAt";
const string API_HISTORY_EXPORT = "History.Export";
const string API_HISTORY_IMPORT = "History.Import";

/* Module Option Keys */
const string OPTION_SEND_CONTEXT_DATA = "SendContextData";
const string OPTION_CONTEXT_SIZE = "ContextSize";
const string OPTION_MAX_TOKENS = "MaxTokens";
const string OPTION_MAX_TURNS = "MaxTurns";
const string OPTION_MODEL_FILE = "ModelFile";
const string OPTION_MODEL_LIST = "ModelList";
const string OPTION_MODEL_TEMPERATURE = "ModelTemperature";
const string OPTION_SYSTEM_INSTRUCTIONS = "SystemInstructions";

/* UI and Status Field Names */
const string FIELD_TOKENS_STREAM = "LLM.TokenStream";
const string FIELD_STATUS_INIT = "Status.Init";
const string FIELD_STATUS_ERROR = "Status.Error";
const string FIELD_DOWNLOAD = "Status.Download";
const string FIELD_DOWNLOAD_ID = "Status.Download.Id";
const string FIELD_DOWNLOAD_TASK = "Status.Download.Task";
const string FIELD_DOWNLOAD_REPOSITORY = "Status.Download.Repository";
const string FIELD_DOWNLOAD_ERROR = "Status.Download.Error";
const string FIELD_DOWNLOAD_PROGRESS = "Status.Download.Progress";

/* Resource Settings */
const string CONFIG_FILE_NAME = "models.yaml";

// ===================================================================
// DATA MODELS AND CONFIGURATION LOADING
// ===================================================================

public class ModelInfo {
  public string Url = "";
  public string Name = "";
  public string Repository = "";
  public string Description = "";
  public string Size = "";
  public string Template = "";
}

/**
 * Loads the list of available models from a YAML configuration file.
 */
public static Dictionary<string, ModelInfo> LoadModelList(string configFilePath = CONFIG_FILE_NAME)
{
    string fullPath = configFilePath;
    try
    {
        string yaml = File.ReadAllText(fullPath);
        var deserializer = new DeserializerBuilder().Build();
        return deserializer.Deserialize<Dictionary<string, ModelInfo>>(yaml);
    }
    catch (Exception ex)
    {
        // Return empty dictionary if file is missing or corrupt
        return new Dictionary<string, ModelInfo>();
    }
}

public class MessagePart {
    [JsonProperty("text")]
    public string Text { get; set; }
}
public class ChatMessage {
    [JsonProperty("role")]
    public string Role { get; set; }
    [JsonProperty("parts")]
    public List<MessagePart> Parts { get; set; } = new List<MessagePart>();
    public static ChatMessage Create(string role, string text) {
        return new ChatMessage { Role = role, Parts = new List<MessagePart> { new MessagePart { Text = text } } };
    }
}

// ===================================================================
// INFERENCE PARAMETERS (Sampling & Stop Sequences)
// ===================================================================

InferenceParams LailamaInferenceParams = new InferenceParams
{
    SamplingPipeline = new DefaultSamplingPipeline
    {
        Temperature = 0.4f, // Lower temperature for more deterministic/factual responses
        TopP = 0.95f,
        RepeatPenalty = 1.2f
    },
    MaxTokens = 1024,

    // ANTI-PROMPTS (Stop Sequences)
    // This list prevents the model from "hallucinating" both sides of the conversation
    // or continuing indefinitely after providing the answer.
    AntiPrompts = new string[]
    {
        // --- GROUP 1: OFFICIAL EOS (End Of Sentence) TOKENS ---
        // Internal markers specific to each model architecture.
        "<|im_end|>",           // ChatML (Qwen, Phi-3, Yi)
        "<|endoftext|>",        // GPT-based standards
        "<|eot_id|>",           // Llama 3
        "<|eom_id|>",           // Llama 3 (End of Message)
        "<|end|>",              // Phi-3
        "<end_of_turn>",        // Gemma 2
        "<|end_of_sentence|>",  // DeepSeek
        "<|end_of_response|>",  // DeepSeek R1 / Reasoning models

        // --- GROUP 2: TURN-START MARKERS ---
        // Used to catch the model if it tries to generate the next User/System turn.
        "<|im_start|>",         // ChatML
        "<|start_header_id|>",  // Llama 3
        "<|user|>",             // Phi-3
        "<start_of_turn>",      // Gemma
        "<|begin_of_sentence|>",// DeepSeek
        "<|start_response|>",   // Reasoning response start
        "Answer: ",             // DeepSeek fallback

        // --- GROUP 3: TEXTUAL FALLBACKS ---
        // Prevents the model from writing plain-text labels like "Assistant:" or "User:".
        "Assistant:",
        "\nAssistant:",
        "Response:",
        "\nResponse:",
        "### Assistant",
        "### Response",
        "\nUser:",
        "\nUser ",
        "User:",
        "### Instruction",
        "### User",
        "\nSystem:",
        "System:",
        "\n\nUser:",
        "\n\nSystem:",
        "\n\nAssistant:"
    }
};

// ===================================================================
// PROMPT TEMPLATING LOGIC
// ===================================================================

/**
 * Wraps the system instructions in the format required by the specific model template.
 */
string GetSystemPrompt(string templateType, string prompt) {
  switch (templateType) {
    case "llama3":
      return $"<|begin_of_text|><|start_header_id|>system<|end_header_id|>\n\n{prompt}\n<|eot_id|>";

    case "phi3":
      return $"{prompt}\n\n";

    case "gemma":
       return $"<start_of_turn>user\n{prompt}<end_of_turn>\n<start_of_turn>model\nOK.<end_of_turn>\n";

    case "alpaca":
    case "openchat":
      return $"{prompt}\n\n";

    case "deepseek":
      return $"<|begin_of_sentence|>{prompt}\n\n";

    case "chatml":
    default:
      return $"<|im_start|>system\n{prompt}\n<|im_end|>\n";
  }
}

/**
 * Wraps user input and prepares the assistant's response header based on the template.
 */
string BuildUserPrompt(string templateType, string userInput) {
  switch (templateType) {
    case "llama3":
      return $"<|start_header_id|>user<|end_header_id|>\n\n{userInput}<|eot_id|><|start_header_id|>assistant<|end_header_id|>\n\n";

    case "phi3":
      return $"<|user|>\n{userInput}<|end|>\n<|assistant|>\n";

    case "alpaca":
      return $"### Instruction:\n{userInput}\n\n### Response:\n";

    case "openchat":
      return $"GPT4 Correct User: {userInput}<|end_of_turn|>GPT4 Correct Assistant:";

    case "gemma":
      return "<start_of_turn>user\n" + userInput + "<end_of_turn>\n<start_of_turn>model\n";

    case "deepseek":
      return $"User:{userInput}\n\nAssistant: ";

    case "chatml":
    default:
      return $"<|im_start|>user\n{userInput}<|im_end|>\n<|im_start|>assistant\n";
  }
}

// ===================================================================
// UTILITY HELPERS AND CONTENT EXTRACTION
// ===================================================================

/**
 * Helper to process the asynchronous token stream from the LLM.
 */
async Task ProcessAsync(IAsyncEnumerable<string> asyncEnumerable, Action<string> callback)
{
    await foreach (string item in asyncEnumerable)
    {
        callback(item);
    }
}

public class ApiCommandExecution
{
    public string ActionId { get; set; }
    public string RequestId { get; set; }
    public string State { get; set; }
    public long DurationMs { get; set; }
    public bool Replayed { get; set; }
    public DateTimeOffset? CompletedAt { get; set; }
    public int Index { get; set; }
    public string Command { get; set; }
    public bool Success { get; set; }
    public object Response { get; set; }
    public string Error { get; set; }
}

public string ReadActionResponse(object input)
{
    var request = Api.Parse(input);
    if (request.Data is byte[] bytes && bytes.Length > 0) return Encoding.UTF8.GetString(bytes);
    if (request.Data is string text && text.Length > 0) return text;
    return WebUtility.UrlDecode(request.OriginalRequest ?? "");
}

public List<string> ExtractResponse(string response)
{
    object result = Api.Call("System.Utility/ActionExecutor/Extract", response);
    if (result == null) throw new InvalidOperationException("AI Action Executor is unavailable.");
    var segments = JToken.FromObject(result) as JArray;
    if (segments == null) throw new InvalidOperationException("Invalid AI Action Executor extraction response.");
    return segments.ToObject<List<string>>();
}

public List<ApiCommandExecution> ExecuteResponse(string response, string requestId = null)
{
    object result = Api.Call("System.Utility/ActionExecutor/Execute", requestId == null ? (object)response : new { requestId, response });
    if (result == null) throw new InvalidOperationException("AI Action Executor is unavailable.");
    var actions = JToken.FromObject(result) as JArray;
    if (actions == null) throw new InvalidOperationException("Invalid AI Action Executor execution response.");
    return actions.ToObject<List<ApiCommandExecution>>();
}

public object ExtractAndExecute(string response)
{
    return Api.Call("System.Utility/ActionExecutor/ExtractAndExecute", response);
}

/**
 * Returns the total available system or container memory in Gigabytes.
 */
public static long GetTotalMemoryGB()
{
    // Returns the total system (or container) memory in bytes
    var stats = GC.GetGCMemoryInfo();
    long totalMemoryBytes = stats.TotalAvailableMemoryBytes;

    // If for any reason it returns 0 or less, use a safe default of 16GB
    if (totalMemoryBytes <= 0) return 16;

    return totalMemoryBytes / 1024 / 1024 / 1024;
}

/**
 * Returns optimized LLama model parameters based on the detected system RAM.
 */
public ModelParams GetOptimizedParams(string modelPath)
{
    long totalRamGB = GetTotalMemoryGB();
    var p = new ModelParams(modelPath);

    // Common settings for all profiles
    p.FlashAttention = true;
    p.UseMemorymap = true;
    p.GpuLayerCount = -1; // Attempt GPU offloading; falls back to CPU automatically if no GPU is detected

    if (totalRamGB <= 8)
    {
        // LOW RAM PROFILE (e.g., Raspberry Pi or older PCs)
        p.ContextSize = 4096;
        p.TypeK = GGMLType.GGML_TYPE_Q4_0;
        p.TypeV = GGMLType.GGML_TYPE_Q4_0;
        p.BatchSize = 128;
        p.UBatchSize = 128;
    }
    else if (totalRamGB <= 16)
    {
        // STANDARD PROFILE (The most common configuration)
        p.ContextSize = 16384;
        p.TypeK = GGMLType.GGML_TYPE_Q4_0;
        p.TypeV = GGMLType.GGML_TYPE_Q4_0;
        p.BatchSize = 512;
        p.UBatchSize = 512;
    }
    else
    {
        // HIGH PERFORMANCE PROFILE (32GB RAM or more)
        p.ContextSize = 32768; // Can be safely increased to 65536 if needed
        p.TypeK = GGMLType.GGML_TYPE_Q8_0; // Use Q8 for higher precision KV cache
        p.TypeV = GGMLType.GGML_TYPE_Q8_0;
        p.BatchSize = 512;
        p.UBatchSize = 512;
    }

    return p;
}

// Diagnostics stay in the history envelope, never in provider message objects.
public class ChatRequestMetrics
{
    readonly dynamic api;
    readonly string storeId;
    readonly bool persist;
    readonly System.Diagnostics.Stopwatch clock = System.Diagnostics.Stopwatch.StartNew();
    readonly DateTimeOffset startedAt = DateTimeOffset.UtcNow;
    public string RequestId { get; } = Guid.NewGuid().ToString("N");
    public object ActionResults { get; private set; }
    public void SetActionResults(object results) { ActionResults = results; }
    public long? FirstTokenMs { get; private set; }
    public long? GenerationMs { get; private set; }
    public long ActionsMs { get; private set; }
    public int ActionCount { get; private set; }
    public int FailedActions { get; private set; }
    bool replySaved;

    public ChatRequestMetrics(dynamic api, string storeId, bool persist = true)
    { this.api = api; this.storeId = storeId; this.persist = persist; }

    public void FirstToken() { if (!FirstTokenMs.HasValue) FirstTokenMs = clock.ElapsedMilliseconds; }
    public void GenerationComplete() { GenerationMs = clock.ElapsedMilliseconds; }
    public void ActionsCompleted(long elapsedMs, int count, int failed)
    { ActionsMs += elapsedMs; ActionCount += count; FailedActions += failed; }
    public object Snapshot(string outcome) => new {
        requestId = RequestId, startedAt = startedAt.ToString("O"), outcome,
        durationMs = clock.ElapsedMilliseconds, firstTokenMs = FirstTokenMs,
        generationMs = GenerationMs, actionsMs = ActionsMs,
        actionCount = ActionCount, failedActions = FailedActions, actions = ActionResults
    };
    public void SaveUser(object message)
    { if (persist) api.Call("System.Utility/ChatHistory/Add", new { StoreId = storeId, Message = message, Metadata = Snapshot("submitted") }); }
    public void SaveReply(object message, string outcome = "completed")
    {
        if (replySaved) return;
        if (persist) api.Call("System.Utility/ChatHistory/Add", new { StoreId = storeId, Message = message, Metadata = Snapshot(outcome) });
        replySaved = true;
    }
    public string Error(string text, string outcome = "error")
    {
        SaveReply(new { role = "model", parts = new[] { new { text } } }, outcome);
        return text;
    }
}


// Native resources are released only after the operation owning them has finished.
// A background cleanup with a bounded stop wait also covers slow native Dispose calls.
public sealed class LailamaNativeLifetime
{
    private readonly object gate = new object();
    private bool stopping;
    private CancellationTokenSource current;
    private TaskCompletionSource<bool> idle;
    private Task cleanup;

    public bool IsStopping { get { lock (gate) return stopping; } }
    public bool CleanupCompleted { get { lock (gate) return cleanup != null && cleanup.IsCompleted; } }

    public bool TryBegin(out CancellationTokenSource cancellation)
    {
        lock (gate)
        {
            cancellation = null;
            if (stopping || current != null) return false;
            cancellation = current = new CancellationTokenSource();
            idle = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
            return true;
        }
    }

    public void End(CancellationTokenSource cancellation)
    {
        lock (gate)
        {
            if (!ReferenceEquals(current, cancellation)) return;
            current = null;
            idle.TrySetResult(true);
        }
        lock (cancellation) cancellation.Dispose();
    }

    public bool CancelCurrent()
    {
        CancellationTokenSource cancellation;
        lock (gate) cancellation = current;
        Cancel(cancellation);
        return cancellation != null;
    }

    private static void Cancel(CancellationTokenSource cancellation)
    {
        if (cancellation == null) return;
        try { lock (cancellation) cancellation.Cancel(); }
        catch (ObjectDisposedException) { } // The owning operation completed concurrently.
    }

    private static void Log(Action<string> log, string message)
    {
        try { log?.Invoke(message); }
        catch { } // The host logger may already be shutting down.
    }

    public bool Stop(Action release, Action<string> log, int timeoutMilliseconds = 5000)
    {
        Task pending;
        lock (gate)
        {
            if (cleanup == null)
            {
                stopping = true;
                var cancellation = current;
                Task drained = current == null ? Task.CompletedTask : idle.Task;
                cleanup = Task.Run(async () =>
                {
                    var elapsed = System.Diagnostics.Stopwatch.StartNew();
                    try
                    {
                        Log(log, "Lailama shutdown: cancellation requested; waiting for native operation.");
                        try { Cancel(cancellation); }
                        catch (Exception ex) { Log(log, "Lailama shutdown cancellation: " + ex.Message); }
                        await drained.ConfigureAwait(false);
                        Log(log, "Lailama shutdown: native operation finished; releasing resources.");
                        release();
                        Log(log, "Lailama shutdown: cleanup completed in " + elapsed.ElapsedMilliseconds + " ms.");
                    }
                    catch (Exception ex) { Log(log, "Lailama shutdown cleanup failed: " + ex.Message); }
                });
            }
            pending = cleanup;
        }
        if (pending.Wait(timeoutMilliseconds)) return true;
        Log(log, "Lailama shutdown: cleanup still pending after " + timeoutMilliseconds +
            " ms; continuing host shutdown without disposing resources in use.");
        return false;
    }
}

